            '<span style="font-size:13px;font-weight:700">'+m.v+'</span></div>';
        }).join('')+'</div>';
    }
    var impactHtml=state.impact
      ?'<div style="margin-top:8px;font-size:12px;color:rgba(255,255,255,.6);line-height:1.6;margin-bottom:'+(state.action?'6px':'0')+'"><span style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:rgba(255,255,255,.3);margin-right:6px">Impacto potencial:</span>'+state.impact+'</div>':'';
    var actionHtml=state.action
      ?'<div style="margin-top:6px;font-size:12px;color:rgba(255,255,255,.5);line-height:1.6"><span style="font-family:Material Icons;font-size:12px;vertical-align:middle;margin-right:4px;color:rgba(255,255,255,.35)">arrow_forward</span>'+state.action+'</div>':''
    var band=BAND[state.level]||BAND['sin-historico'];
