        '<span style="font-size:11px;color:rgba(255,255,255,.75);font-variant-numeric:tabular-nums">'+t+'</span>'+
      '</div>';
    var htmlContent=bandaHtml+
      '<div style="font-size:13px;font-weight:500;color:rgba(255,255,255,.92);line-height:1.65;margin-bottom:'+(state.impact||state.action?'10px':'0')+'">'+state.title+'</div>'+
      impactHtml+actionHtml+metricsHtml

    var icText=el('ic-text'); if(icText) icText.innerHTML=htmlContent;
    set('ic-date','Actualizado hoy '+t+' · análisis basado en telemetría real');

    /* Métricas externas icm-1/2/3 */
    if(D.energyToday!==null){
