  function renderSec01(){
    var pa=lat('potencia_activa_total');
    var fp=(lat('factor_potencia_fase_a')+lat('factor_potencia_fase_b')+lat('factor_potencia_fase_c'))/3;
    set('kv-pa',Math.round(pa).toLocaleString('es-PE'));
    var paChip=el('kch-pa');
    if(paChip){
      var paKw=pa/1000;
      if(paKw>KW_MAX)        {paChip.textContent='⚠ Sobre pico ('+paKw.toFixed(1)+' kW)';paChip.className='kc-chip alert';}
      else if(paKw>KW_MAX*.8){paChip.textContent='Demanda alta del día ('+paKw.toFixed(1)+' kW)';paChip.className='kc-chip warn';}
      else                    {paChip.textContent=paKw.toFixed(1)+' kW activos';paChip.className='kc-chip';}
    }
    set('kv-fp',fmtFP(fp));
    var fpEl=el('kch-fp');
    if(fpEl){
      if(fp>=0.97)        {fpEl.textContent='Excelente';   fpEl.className='kc-chip ok';}
