  function renderSec04(){
    var rawA=D.demand.potencia_activa_fase_a||[], rawB=D.demand.potencia_activa_fase_b||[];
    var rawC=D.demand.potencia_activa_fase_c||[];
    if(rawA.length===0) return;
    var toKw=function(p){return parseFloat(p.value)/1000;};
    var dA=rawA.map(toKw), dB=rawB.map(toKw), dC=rawC.map(toKw);
    var labels=rawA.map(function(p){var d=new Date(+p.ts);return pad(d.getHours())+':00';});
    var eCanvas=el('energy-canvas');
    if(eCanvas){
      if(CH.energy){CH.energy.destroy();CH.energy=null;}
      CH.energy=new Chart(eCanvas,{
        type:'line',
        data:{labels:labels,datasets:[
          {label:'Fase A',data:dA,borderColor:'#00EBC8',backgroundColor:'rgba(0,235,200,.5)',borderWidth:1.5,pointRadius:0,fill:true,tension:.4},
          {label:'Fase B',data:dB,borderColor:'#00008C',backgroundColor:'rgba(0,0,140,.45)',borderWidth:1.5,pointRadius:0,fill:true,tension:.4},
          {label:'Fase C',data:dC,borderColor:'#6366F1',backgroundColor:'rgba(99,102,241,.4)',borderWidth:1.5,pointRadius:0,fill:true,tension:.4}
        ]},
        options:{
          responsive:true,maintainAspectRatio:false,interaction:{intersect:false,mode:'index'},
          plugins:{legend:{display:false},tooltip:{backgroundColor:'white',titleColor:'#5A6E8A',bodyColor:'#0D1B2E',borderColor:'#D4E0EE',borderWidth:1,
            callbacks:{label:function(c){return ' '+c.dataset.label+': '+c.parsed.y.toFixed(2)+' kW';}}}},
          scales:{
            x:{grid:{color:'rgba(212,224,238,.5)',drawBorder:false},ticks:{color:'#96AABF',font:{size:10},maxTicksLimit:12}},
            y:{stacked:true,grid:{color:'rgba(212,224,238,.5)',drawBorder:false},ticks:{color:'#96AABF',font:{size:10},callback:function(v){return v.toFixed(1)+' kW';}}}
          }
        }
      });
    }
    document.querySelectorAll('#anal-time-btns .tbtn').forEach(function(btn){
      var newBtn=btn.cloneNode(true); btn.parentNode.replaceChild(newBtn,btn);
      newBtn.addEventListener('click',function(){
        document.querySelectorAll('#anal-time-btns .tbtn').forEach(function(b){b.classList.remove('active');}); this.classList.add('active');
        var period=this.getAttribute('data-p');
        if(period==='hoy'){
          if(!CH.energy) return;
          CH.energy.data.labels=rawA.map(function(p){var d=new Date(+p.ts);return pad(d.getHours())+':00';});
          CH.energy.data.datasets[0].data=rawA.map(toKw); CH.energy.data.datasets[1].data=rawB.map(toKw);
          CH.energy.data.datasets[2].data=rawC.map(toKw); CH.energy.update('none');
        } else {
          var days=period==='semana'?7:30;
          var keys='potencia_activa_fase_a,potencia_activa_fase_b,potencia_activa_fase_c';
          api(tsUrl(keys,daysAgo(days),nowMs(),86400000,'AVG',50),function(d){
            if(!CH.energy) return;
            var rA=d.potencia_activa_fase_a||[], rB=d.potencia_activa_fase_b||[], rC=d.potencia_activa_fase_c||[];
            var MESES=['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
            CH.energy.data.labels=rA.map(function(p){var dt=new Date(+p.ts);return pad(dt.getDate())+' '+MESES[dt.getMonth()];});
            CH.energy.data.datasets[0].data=rA.map(toKw); CH.energy.data.datasets[1].data=rB.map(toKw);
            CH.energy.data.datasets[2].data=rC.map(toKw); CH.energy.update('none');
          });
        }
      });
    });
    function _dSt(arr){ if(!arr||!arr.length) return{avg:null,mx:null,mn:null}; var vs=arr.map(function(p){return parseFloat(p.value)/1000;}), s=vs.reduce(function(a,b){return a+b;},0); return{avg:s/vs.length,mx:Math.max.apply(null,vs),mn:Math.min.apply(null,vs)}; }
    var stT=_dSt(D.demand&&D.demand.potencia_activa_total), stA=_dSt(D.demand&&D.demand.potencia_activa_fase_a);
    var stB=_dSt(D.demand&&D.demand.potencia_activa_fase_b), stC=_dSt(D.demand&&D.demand.potencia_activa_fase_c);
    var avgTot=stT.avg||1, enA=D.energyToday!==null?D.energyToday*(stA.avg||0)/avgTot:null;
    var enB=D.energyToday!==null?D.energyToday*(stB.avg||0)/avgTot:null, enC=D.energyToday!==null?D.energyToday*(stC.avg||0)/avgTot:null;
    function _f(v,unit){return v!==null&&v!==undefined?v.toFixed(v>10?1:2)+(unit?' '+unit:''):'—';}
    var statsRows=[
      {l:'Sistema Total',c:'#0F172A',t:_f(D.energyToday,'kWh'),av:_f(stT.avg,'kW'),mx:_f(stT.mx,'kW'),mn:_f(stT.mn,'kW')},
      {l:'Fase A',c:'#00EBC8',t:_f(enA,'kWh'),av:_f(stA.avg,'kW'),mx:_f(stA.mx,'kW'),mn:_f(stA.mn,'kW')},
      {l:'Fase B',c:'#00008C',t:_f(enB,'kWh'),av:_f(stB.avg,'kW'),mx:_f(stB.mx,'kW'),mn:_f(stB.mn,'kW')},
      {l:'Fase C',c:'#6366F1',t:_f(enC,'kWh'),av:_f(stC.avg,'kW'),mx:_f(stC.mx,'kW'),mn:_f(stC.mn,'kW')},
    ];
    var stbody=el('stats-tbody');
    if(stbody) stbody.innerHTML=statsRows.map(function(r,i){
      var bg=i%2===1?'background:rgba(244,248,252,.65)':'';
      return '<tr style="'+bg+'"><td><div class="stt-name"><span class="stt-dot" style="background:'+r.c+'"></span>'+r.l+'</div></td>'+
        '<td class="stt-val">'+r.t+'</td><td class="stt-val">'+r.av+'</td><td class="stt-val">'+r.mx+'</td><td class="stt-val">'+r.mn+'</td></tr>';
    }).join('');
  }

  function renderCostCard(){
    if(D.energyToday===null) return;
    var en=D.energyToday, now=new Date(), daysM=new Date(now.getFullYear(),now.getMonth()+1,0).getDate();
    var hoursElapsed=Math.max((now.getTime()-todayStart())/3600000,0.5), proj=(en/hoursElapsed*24)*daysM;
    set('cc-tar',TARIFA.toFixed(2)); set('cc-kwh',en.toFixed(1)+' kWh');
    set('cc-hoy',fmtSol(en*TARIFA)); set('cc-proj-k','~'+Math.round(proj).toLocaleString('es-PE')+' kWh');
    set('cc-proj-s','≈ '+fmtSol(proj*TARIFA));
    var mCanvas=el('monthly-canvas'); if(!mCanvas) return;
    if(CH.monthly){CH.monthly.destroy();CH.monthly=null;}
    var pts=D.monthly.slice(-7), barData=[], barLabels=[];
    var MESES=['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
    for(var i=1;i<pts.length;i++){
      var delta=Math.max(0,(pts[i].v-pts[i-1].v)/1000);
      barData.push(Math.round(delta)); barLabels.push(MESES[new Date(pts[i].ts).getMonth()]);
    }
    if(barData.length===0){
      var mCanvas2=el('monthly-canvas');
      if(mCanvas2&&mCanvas2.parentElement) mCanvas2.parentElement.innerHTML='<div style="font-size:11px;color:#96AABF;padding:8px 0;text-align:center">Histórico disponible tras el primer mes completo</div>';
      return;
    }
    CH.monthly=new Chart(mCanvas,{
      type:'bar',
      data:{labels:barLabels,datasets:[{data:barData,backgroundColor:'rgba(255,255,255,.55)',borderRadius:3}]},
      options:{responsive:true,maintainAspectRatio:false,
        plugins:{legend:{display:false},tooltip:{callbacks:{label:function(c){return ' '+c.parsed.y.toLocaleString('es-PE')+' kWh';}}}}  ,
        scales:{x:{display:false},y:{display:false}}}
    });
  }

